'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var resolveLayout = require( '@stdlib/blas/base/layout-resolve-enum' );
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var validate = require( './validate.js' );
var validateArrays = require( './validate_arrays.js' );


// MAIN //

/**
* Creates the public interfaces for a numerical implementation.
*
* @private
* @param {Function} base - numerical implementation
* @returns {Function} public interface
*/
function factory( base ) {
	setReadOnly( dlantr, 'ndarray', ndarray );
	return dlantr;

	/**
	* Computes a norm of a triangular or trapezoidal matrix.
	*
	* @private
	* @param {(string|integer)} order - storage layout
	* @param {string} norm - norm type
	* @param {(string|integer)} uplo - triangle type
	* @param {(string|integer)} diag - diagonal type
	* @param {NonNegativeInteger} M - number of rows
	* @param {NonNegativeInteger} N - number of columns
	* @param {Float64Array} A - input matrix
	* @param {PositiveInteger} LDA - leading dimension
	* @param {Float64Array} work - infinity norm scratch storage
	* @throws {TypeError} invalid option or storage type
	* @throws {RangeError} invalid dimension, leading dimension, or storage length
	* @returns {number} norm
	*/
	function dlantr( order, norm, uplo, diag, M, N, A, LDA, work ) {
		var opts;
		var sa1;
		var sa2;
		var l;

		l = resolveLayout( order );
		if ( l === null ) {
			throw new TypeError( 'invalid argument. First argument must be a valid order.' );
		}
		opts = validate( norm, uplo, diag, M, N );
		if (
			!isPositiveInteger( LDA ) ||
			( l === 101 && LDA < N ) ||
			( l === 102 && LDA < M )
		) {
			throw new RangeError( 'invalid argument. Leading dimension must be at least max(1,N) for row-major storage or max(1,M) for column-major storage.' );
		}
		if ( l === 102 ) {
			sa1 = 1;
			sa2 = LDA;
		} else {
			sa1 = LDA;
			sa2 = 1;
		}
		validateArrays( opts[0], M, N, A, sa1, sa2, 0, work, 1, 0 );
		return base( opts[0], opts[1], opts[2], M, N, A, sa1, sa2, 0, work, 1, 0 ); // eslint-disable-line max-len
	}

	/**
	* Computes a matrix norm using alternative indexing semantics.
	*
	* @private
	* @param {string} norm - norm type
	* @param {(string|integer)} uplo - triangle type
	* @param {(string|integer)} diag - diagonal type
	* @param {NonNegativeInteger} M - number of rows
	* @param {NonNegativeInteger} N - number of columns
	* @param {Float64Array} A - matrix storage
	* @param {integer} strideA1 - row stride
	* @param {integer} strideA2 - column stride
	* @param {NonNegativeInteger} offsetA - matrix offset
	* @param {Float64Array} work - scratch storage
	* @param {NonZeroInteger} strideWork - workspace stride
	* @param {NonNegativeInteger} offsetWork - workspace offset
	* @throws {TypeError} invalid option or storage type
	* @throws {RangeError} invalid dimensions or indexed storage
	* @returns {number} norm
	*/
	function ndarray( norm, uplo, diag, M, N, A, strideA1, strideA2, offsetA, work, strideWork, offsetWork ) { // eslint-disable-line max-len, max-params
		var opts = validate( norm, uplo, diag, M, N );
		validateArrays( opts[0], M, N, A, strideA1, strideA2, offsetA, work, strideWork, offsetWork ); // eslint-disable-line max-len
		return base( opts[0], opts[1], opts[2], M, N, A, strideA1, strideA2, offsetA, work, strideWork, offsetWork ); // eslint-disable-line max-len
	}
}


// EXPORTS //

module.exports = factory;
